import { defineConfig, type DefaultTheme } from 'vitepress';

// ADR-0201. The site is served from the apex of its own domain, so `base` is the
// root; the sitemap still needs absolute URLs Search Console can fetch.
const BASE = '/';
const ORIGIN = 'https://rahdar.dev/';

const REPO = 'https://github.com/sudoitir/rahdar';

/** The reference tree is generated by `scripts/prepare-docs.ts`; the sidebar is not. */
function reference(labels: {
  reference: string;
  architecture: string;
  adr: string;
  changelog: string;
}): DefaultTheme.SidebarItem {
  return {
    text: labels.reference,
    items: [
      { text: labels.architecture, link: '/reference/architecture' },
      { text: labels.adr, link: '/reference/adr/' },
      { text: labels.changelog, link: '/reference/changelog/' },
    ],
  };
}

